urlset:

  https://{{ domain }}/
  daily
  1.0

{% for slug in menus %}

  https://{{ domain }}/{{ slug }}
  weekly
  0.8

{% endfor %}
{% for p in products %}

  https://{{ domain }}/{{ p.slug }}
  {% if p.lastmod %}{{ p.lastmod.strftime('%Y-%m-%d') }}{% endif %}
  monthly
  0.9

{% endfor %}
{% for row in news_rows %}

  https://{{ domain }}/{{ row.slug }}
  {% set _d = row.updated_at or row.created_at %}
  {% if _d %}{{ _d.strftime('%Y-%m-%d') }}{% endif %}
  monthly
  0.6

{% endfor %}
